&lt;p&gt;&lt;span style="font-family:wordvisicarriagereturn_msfontservice,calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;br /&gt;
&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;PORTLAND, Ore.&lt;/span&gt;&lt;span style="color:rgb(102, 102, 102); font-family:lato,lato_embeddedfont,lato_msfontservice,sans-serif"&gt; &lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;(Nov. 20, 2025) &lt;/span&gt;&lt;span style="color:rgb(102, 102, 102); font-family:lato,lato_embeddedfont,lato_msfontservice,sans-serif"&gt;&mdash; &lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;Heading into the holiday season, Pacific Power is reminding customers to be vigilant about fraudulent communications from scammers posing as utility representatives. This activity tends to increase during this time of year.&amp;nbsp;&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;Customers can protect themselves from these types of schemes by being aware of the following facts:&amp;nbsp;&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; position: relative;"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;em&gt;Scammers will often tell you that your service is scheduled to be interrupted in the next 30 to 60 minutes.&amp;nbsp;&lt;/em&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;Fact:&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; Pacific Power &lt;/span&gt;&lt;strong&gt;will not&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; contact any customer demanding immediate payment to avoid disconnecting their service the same day. Be suspicious of anyone who contacts you demanding on-the-spot payment.&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; position: relative;"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;em&gt;Fraudsters may ask you to purchase a prepaid card and tell them the card information over the phone.&amp;nbsp;&lt;/em&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;Fact:&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; Pacific Power &lt;/span&gt;&lt;strong&gt;does not&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; ask customers to make payments by purchasing a prepaid card. You and other customers can always choose how you would like to make payments.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; position: relative;"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;em&gt;If you receive one of these calls, ask the caller to state your account number and compare it with the number listed on your bill.&lt;/em&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;Fact:&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; Pacific Power customer service employees &lt;/span&gt;&lt;strong&gt;will always&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; have your correct account number.&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; position: relative;"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;em&gt;Scammers have increasingly used text messages as a means of targeting victims.&amp;nbsp;&lt;/em&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;Fact:&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; Pacific Power &lt;/span&gt;&lt;strong&gt;will not&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; demand payment via text message. Pacific Power encourages customers to set up their online billing profile at Pay My Bill (on PacificPower.net) where they can pay bills and review statements.&amp;nbsp;&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;Scammers may use a sophisticated and deceptive tactic that makes it appear to caller ID systems that the call is coming from Pacific Power when it is not. Hang up if you receive a suspicious or concerning call, and call our customer service line directly at 1-888-221-7070.&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;Pacific Power is asking customers to report information about any scam call received, including the phone number the person is calling from and any information that may help to track down the fraudsters.&amp;nbsp;&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p style="text-align:center"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p style="text-align:center"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;###&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
